def cap(path):
 p=Path(path);raw=p.read_bytes();return {'path':str(p),'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
def save(name,value):
 p=OUT/name;raw=(json.dumps(value,sort_keys=True,indent=2,ensure_ascii=True,allow_nan=False)+'\n').encode()
 with p.open('wb')as f:f.write(raw)  # Own unselected draft metadata, frozen only at final handoff.
 return cap(p)
sources={k:cap(ROOT/v)for k,v in files.items()}
regions={}
for role,relative in files.items():
 if not relative.endswith('.py'):continue
 tree=ast.parse((ROOT/relative).read_text(),filename=relative)
 def visit(body,prefix=''):
  for node in body:
   if isinstance(node,(ast.ClassDef,ast.FunctionDef)):
    name=prefix+node.name
    regions[role+':'+name]={'source_role':role,'line':node.lineno,'end_line':node.end_lineno}
    if isinstance(node,ast.ClassDef):visit(node.body,name+'.')
 visit(tree.body)
def ref(role,name=None):
 result={'source_role':role}
 if name is not None:result.update(regions[role+':'+name])
 return result
